        public static InterestDef Get(string id) => All.Find(x => x.id == id);
        public static string Name(string id) => Get(id)?.name ?? id;

        /// <summary>Подобрать интересы новой лисичке: 1–3, по характеру с долей случайности.</summary>
        public static List<string> Random(Personality p)
        {
            var res = new List<string>();
            int n = UnityEngine.Random.Range(1, Max + 1);
            for (int k = 0; k < n; k++)
            {
                float sum = 0;
                var w = new List<(InterestDef d, float w)>();
                foreach (var d in All)
                {
                    if (res.Contains(d.id)) continue;
                    float x = 1f + d.o * (p.O - 5.5f) * 0.12f + d.e * (p.E - 5.5f) * 0.12f + d.c * (p.C - 5.5f) * 0.1f;
                    x = Mathf.Max(0.15f, x);
                    w.Add((d, x)); sum += x;
                }
                float r = UnityEngine.Random.value * sum;
                foreach (var c in w) { r -= c.w; if (r <= 0) { res.Add(c.d.id); break; } }
            }
            return res;
        }

        /// <summary>Тема разговора: чаще общий интерес, иначе — свой, иначе — без темы (о жизни).</summary>
        public static string PickTopic(Fox a, Fox b)
        {
            if (a == null || a.interests.Count == 0) return null;
            var shared = a.interests.FindAll(x => b != null && b.interests.Contains(x));
            if (shared.Count > 0 && UnityEngine.Random.value < 0.6f) return shared[UnityEngine.Random.Range(0, shared.Count)];
            if (UnityEngine.Random.value < 0.5f) return a.interests[UnityEngine.Random.Range(0, a.interests.Count)];
            return null;
        }

        /// <summary>Реплика по теме для разговора (social — имя действия), или null.</summary>
        public static string Line(string topic, string social, Fox me, Fox other)
        {
            var d = Get(topic);
            if (d == null) return null;
            string[] pool = social == "Пошутить" ? d.jokes : social == "Обсудить идеи" ? d.ideas : social == "Рассказать историю" ? d.stories : social == "Поболтать" ? d.talks : null;
            if (pool == null || pool.Length == 0) return null;
            return Phrases.Fill(pool[UnityEngine.Random.Range(0, pool.Length)], me, other);
        }

        /// <summary>Насколько тема меняет шанс понравиться: свой интерес — легче, чужой — шутка может не дойти.</summary>
        public static float ChanceShift(string topic, string social, Fox listener)
        {
            if (topic == null || listener == null) return 0f;
            bool shares = listener.interests.Contains(topic);
            if (social == "Пошутить") return shares ? 0.28f : -0.25f;
            return shares ? 0.2f : -0.1f;
        }

